 select \'YFL_\' || trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_7chefs_tax_sales union select \'YFL_\' || trim(replace(\"Component SKU\", \'`\', \'\')) as component_sku, \"Component SKU Name\" as product_name from HOX_DB.MAPLEMONK.easyecom_hox_7chefs_tax_returns )as o where 1= 1 QUALIFY row_number() over(partition by component_sku order by product_name) = 1 ), product_base as ( select o.* from ( select distinct sku as skucode, product_name, CATEGORY_NAME from HOX_DB.MAPLEMONK.easyecom_yflhome_product_master union select distinct sku as skucode, product_name, CATEGORY_NAME from HOX_DB.MAPLEMONK.easyecom_sevenchef_product_master )as o where 1=1 Qualify row_number() over (partition by skucode order by 1) = 1 ), product_base_sheet as ( select o.* from ( select distinct SKU_CODE, PRODUCT_TYPES from HOX_DB.MAPLEMONK.yfl_sevenchef_sku_category )as o where 1=1 Qualify row_number() over (partition by SKU_CODE order by 1) = 1 ), spends_data as ( select ads_date, \'Zepto Secondary\' as marketplace, brand as brand, sku, sum(SPEND) as final_spend from HOX_DB.MAPLEMONK.HOX_DB_zepto_secondary_MARKETING group by 1,2,3,4 ), secondary_sales as ( select coalesce(o.order_Date,a.ads_date) as order_date, coalesce(o.brand_name, a.brand)as brand_name, o.sku_number, o.CITY, coalesce(o.marketplace, a.marketplace) as marketplace, o.quantity, o.revenue, o.TAXABLE_VALUE, coalesce(o.sku,a.sku) as sku, o.product_name, o.category_name, coalesce(div0(final_spend, count(1) over (partition by coalesce(o.MARKETPLACE, a.MARKETPLACE), coalesce(date(o.order_Date), a.ads_date), lower(coalesce(o.brand_name, a.brand)), coalesce(o.sku, a.sku) order by 1)),0) as final_spend from hox_db.maplemonk.HOX_ZEPTO_retailez_secondary_sales_consolidated as o full outer join spends_data as a on o.order_date = a.ads_date and lower(o.marketplace) = lower(a.marketplace) and lower(o.brand_name) = lower(a.brand) and lower(o.sku) = lower(a.sku) ) select case when lower(marketplace) like \'%zepto%\' then \'Easyecom YFL sale\' when lower(marketplace) like \'%retailez%\' then \'Amazon Sales\' end as REPORT_TYPE, null as COMPANY_NAME, null as SELLER_GST, lower(marketplace) as marketplace, brand_name ||\'_\' || sku || \'_\' || marketplace || \'_\' || order_Date || \'_\' || \'_\' || quantity || \'_\' || city as REFERENCE_CODE, case when lower(marketplace) like \'%zepto%\' then \'B2C\' when lower(marketplace) like \'%retailez%\' then \'Amazon B2C\' end as ORDER_TYPE, \'Shipped\' as ORDER_STATUS, \'Sold\' as INVOICE_STATUS, order_Date as report_date, quantity as PARENT_QUANTITY, quantity, sku, brand_name as brand, revenue as INVOICE_AMT, revenue as SELLING_PRICE, abs(revenue) as ABSOLUTE_INVOICE_AMOUNT, TAXABLE_VALUE as TAX_EXCLUSIVE_GROSS, abs(TAXABLE_VALUE) as ABS_TAX_EXCLUSIVE_GROSS, 0 as TOTAL_TAX_AMOUNT, date(date_trunc(\'month\', order_Date)) as REPORT_MONTH, date(DATE_TRUNC(\'week\', date(order_Date) + INTERVAL \'1 day\')) - INTERVAL \'1 day\' as report_week, 0 as COST, 0 as COGS, 0 as weight, 0 as TOTAL_WEIGHT, final_spend, null as sku_type, a.PRODUCT_TYPE, 0 as EASYECOM_COST, 0 as INTERAKT_COST, 0 as CLICKPOST_COST, \'manufacturer\' as PACKAGING_BOX, 0 as PACKAGING_COST, \'sales\' as SALES_TYPE, \'sales\' as SALES_ORDER_TYPE, \'shipped\' as NEW_STATUS, quantity as NEW_QUANTITY, revenue as NEW_INVOICE_AMT, revenue as NEW_SELLING_PRICE, abs(revenue) as NEW_ABS_INVOICE_AMT, TAXABLE_VALUE as NEW_TAX_EXCLUSIVE_GROSS, abs(TAXABLE_VALUE) as NEW_ABS_TAX_EXCLUSIVE_GROSS, quantity as GROSS_QUANTITY, abs(revenue) as GROSS_ABS_INVOICE_AMT, revenue as GROSS_SP, abs(TAXABLE_VALUE) as GROSS_ABS_TAXABLE_VALUE, quantity as RETURN_QUANTITY, 0 as RETURN_ABS_INVOICE_AMT, 0 as RETURN_SP, 0 as RETURN_ABS_TAXABLE_VALUE, coalesce(o.product_name, b.product_name, d.product_name) as product_name, quantity as NET_QUANTITY, revenue as NET_REVENUE, TAXABLE_VALUE as NET_TAXABLE_VALUE, coalesce(o.category_name, c.PRODUCT_TYPES, d.category_name) as category_name, city from secondary_sales o left join product_details a on lower(o.sku) = lower(a.sku_id) left join product_names b on lower(o.sku) = lower(b.component_sku) left join product_base d on lower(o.sku) = lower(d.skucode) left join product_base_sheet c on lower(o.sku) = lower(c.SKU_CODE) union select *, null as city from hox_db.maplemonk.HOX_YFL_7chef_tax_summary where lower(marketplace) not in (\'b2b - zepto\', \'retailez\')",
